DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[Vendor]([BusinessEntityID],[AccountNumber],[Name],[CreditRating],[PreferredVendorStatus],[ActiveFlag],[PurchasingWebServiceURL],[ModifiedDate],LoadBatchID) SELECT S.[BusinessEntityID],S.[AccountNumber],S.[Name],S.[CreditRating],S.[PreferredVendorStatus],S.[ActiveFlag],S.[PurchasingWebServiceURL],S.[ModifiedDate],@B FROM ssis_flow.Delta_Vendor S;
INSERT stg.[Vendor]([BusinessEntityID],[AccountNumber],[Name],[CreditRating],[PreferredVendorStatus],[ActiveFlag],[PurchasingWebServiceURL],[ModifiedDate],LoadBatchID) SELECT [BusinessEntityID],[AccountNumber],[Name],[CreditRating],[PreferredVendorStatus],[ActiveFlag],[PurchasingWebServiceURL],[ModifiedDate],@B FROM etl_raw.[Vendor];
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.Vendor','I',@Next,(SELECT R.[BusinessEntityID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[Vendor] R;
END ELSE BEGIN
SELECT [BusinessEntityID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_Vendor FROM ssis_flow.Delta_Vendor;
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.Vendor',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[BusinessEntityID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_Vendor C LEFT JOIN etl_raw.[Vendor] R ON R.[BusinessEntityID]=C.[BusinessEntityID];
DELETE R FROM etl_raw.[Vendor] R JOIN #CT_Vendor C ON R.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[AccountNumber]=S.[AccountNumber],R.[Name]=S.[Name],R.[CreditRating]=S.[CreditRating],R.[PreferredVendorStatus]=S.[PreferredVendorStatus],R.[ActiveFlag]=S.[ActiveFlag],R.[PurchasingWebServiceURL]=S.[PurchasingWebServiceURL],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[Vendor] R JOIN #CT_Vendor C ON R.[BusinessEntityID]=C.[BusinessEntityID] JOIN ssis_flow.Delta_Vendor S ON S.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[Vendor]([BusinessEntityID],[AccountNumber],[Name],[CreditRating],[PreferredVendorStatus],[ActiveFlag],[PurchasingWebServiceURL],[ModifiedDate],LoadBatchID) SELECT S.[BusinessEntityID],S.[AccountNumber],S.[Name],S.[CreditRating],S.[PreferredVendorStatus],S.[ActiveFlag],S.[PurchasingWebServiceURL],S.[ModifiedDate],@B FROM #CT_Vendor C JOIN ssis_flow.Delta_Vendor S ON S.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[Vendor] R WHERE R.[BusinessEntityID]=S.[BusinessEntityID]);
INSERT stg.[Vendor]([BusinessEntityID],[AccountNumber],[Name],[CreditRating],[PreferredVendorStatus],[ActiveFlag],[PurchasingWebServiceURL],[ModifiedDate],LoadBatchID) SELECT R.[BusinessEntityID],R.[AccountNumber],R.[Name],R.[CreditRating],R.[PreferredVendorStatus],R.[ActiveFlag],R.[PurchasingWebServiceURL],R.[ModifiedDate],@B FROM etl_raw.[Vendor] R JOIN #CT_Vendor C ON R.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;